package net.civeira.phylax.features.access.userprofile.domain.valueholder;

import java.util.Optional;

import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.features.access.userprofile.domain.UserProfile;
import net.civeira.phylax.features.access.userprofile.domain.valueobject.GenderVO;

@RequiredArgsConstructor
public class GenderValueHolder<T> {

  /**
   * @autogenerated ValueHolderGenerator
   */
  private final T holder;

  /**
   * @autogenerated ValueHolderGenerator
   */
  private Optional<GenderVO> value = Optional.empty();

  /**
   * @autogenerated ValueHolderGenerator
   * @param gender
   * @return
   */
  public T gender(GenderVO gender) {
    this.value = Optional.of(gender);
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param gender
   * @return
   */
  public T gender(Optional<GenderVO> gender) {
    this.value = gender;
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param gender
   * @return
   */
  public T gender(String gender) {
    this.value = Optional.of(GenderVO.from(gender));
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T genderNull() {
    this.value = Optional.empty();
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<String> getGender() {
    return value.flatMap(GenderVO::getGender);
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<GenderVO> getGenderValue() {
    return value;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param original
   * @param fails
   * @return
   */
  public GenderVO readGender(final Optional<UserProfile> original, final ConstraintFailList fails) {
    return value.orElse(original.map(UserProfile::getGenderValue).orElseGet(GenderVO::nullValue));
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T unsetGender() {
    value = Optional.empty();
    return holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param field
   * @return
   */
  public T unsetGenderIfMatches(final String field) {
    if ("gender".equals(field)) {
      value = Optional.empty();
    }
    return holder;
  }
}
